class HashTable:
    def __init__(self, size=8):
        self.buckets = [[] for _ in range(size)]

    def _bucket(self, key):
        return self.buckets[hash(key) % len(self.buckets)]

    def put(self, key, value):
        b = self._bucket(key)
        for pair in b:
            if pair[0] == key:
                pair[1] = value
                return
        b.append([key, value])

    def get(self, key):
        for k, v in self._bucket(key):
            if k == key:
                return v
        raise KeyError(key)

t = HashTable()
t.put("apple", 3); t.put("pear", 5); t.put("apple", 4)
print(t.get("apple"), t.get("pear"))   # 4 5

import hashlib

class Bloom:
    def __init__(self, bits=1024, hashes=3):
        self.bits, self.hashes, self.array = bits, hashes, bytearray(bits)

    def _positions(self, item):
        for i in range(self.hashes):
            digest = hashlib.sha256(f"{i}:{item}".encode()).digest()
            yield int.from_bytes(digest[:8], "big") % self.bits

    def add(self, item):
        for p in self._positions(item):
            self.array[p] = 1

    def might_contain(self, item):
        return all(self.array[p] for p in self._positions(item))

b = Bloom()
for word in ["red", "green", "blue"]:
    b.add(word)
print(b.might_contain("red"), b.might_contain("purple"))   # True False

import bisect, hashlib

def h(x):
    return int(hashlib.md5(str(x).encode()).hexdigest(), 16)

class Ring:
    def __init__(self, servers, replicas=50):
        self.points = sorted((h(f"{s}#{i}"), s) for s in servers for i in range(replicas))
        self.keys = [p for p, _ in self.points]

    def server_for(self, key):
        i = bisect.bisect(self.keys, h(key)) % len(self.points)
        return self.points[i][1]

keys = [f"user{i}" for i in range(1000)]
before = Ring(["A", "B", "C"])
after = Ring(["A", "B", "C", "D"])
moved = sum(before.server_for(k) != after.server_for(k) for k in keys)
print(moved, "of 1000 keys moved")     # roughly 250, where hash-mod-N would move about 750

