        self.value, self.left, self.right = value, left, right

expr = Node("*", Node("+", Node(3), Node(4)), Node(5))

def evaluate(n):
    if isinstance(n.value, int):
        return n.value
    a, b = evaluate(n.left), evaluate(n.right)
    return a + b if n.value == "+" else a * b

print(evaluate(expr))   # 35

class BST:
    def __init__(self):
        self.root = None

    def insert(self, key):
        def go(node):
            if node is None:
                return [key, None, None]
            side = 1 if key < node[0] else 2
            node[side] = go(node[side])
            return node
        self.root = go(self.root)

    def in_order(self, node="root"):
        node = self.root if node == "root" else node
        if node:
            yield from self.in_order(node[1])
            yield node[0]
            yield from self.in_order(node[2])

t = BST()
for k in [50, 30, 70, 20, 40, 60, 80]:
    t.insert(k)
print(list(t.in_order()))    # [20, 30, 40, 50, 60, 70, 80]

class Node:
    def __init__(self, key, left=None, right=None):
        self.key, self.left, self.right = key, left, right

def rotate_right(top):
    new_top = top.left
    top.left, new_top.right = new_top.right, top
    return new_top

def in_order(n):
    return in_order(n.left) + [n.key] + in_order(n.right) if n else []

tree = Node(3, Node(2, Node(1)))          # a left-leaning chain
print(in_order(tree))                     # [1, 2, 3]
tree = rotate_right(tree)
print(tree.key, in_order(tree))           # 2 [1, 2, 3]: same order, better shape

class Trie:
    def __init__(self):
        self.children, self.end = {}, False

    def add(self, word):
        node = self
        for ch in word:
            node = node.children.setdefault(ch, Trie())
        node.end = True

    def with_prefix(self, prefix):
        node = self
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]
        out = []
        def walk(n, acc):
            if n.end:
                out.append(prefix + acc)
            for c, child in sorted(n.children.items()):
                walk(child, acc + c)
        walk(node, "")
        return out

t = Trie()
for w in ["car", "card", "care", "cat", "dog"]:
    t.add(w)
print(t.with_prefix("car"))    # ['car', 'card', 'care']

class SegTree:
    def __init__(self, data):
        self.n = len(data)
        self.t = [0] * self.n + list(data)
        for i in range(self.n - 1, 0, -1):
            self.t[i] = self.t[2 * i] + self.t[2 * i + 1]

    def update(self, i, value):
        i += self.n
        self.t[i] = value
        while i > 1:
            i //= 2
            self.t[i] = self.t[2 * i] + self.t[2 * i + 1]

    def query(self, lo, hi):            # sum of data[lo:hi]
        total, lo, hi = 0, lo + self.n, hi + self.n
        while lo < hi:
            if lo & 1:
                total += self.t[lo]; lo += 1
            if hi & 1:
                hi -= 1; total += self.t[hi]
            lo //= 2; hi //= 2
        return total

s = SegTree([5, 3, 8, 6, 2, 7])
print(s.query(1, 5))     # 3+8+6+2 = 19
s.update(2, 10)
print(s.query(1, 5))     # 21

from collections import deque

tree = ("A", ("B", ("D", None, None), ("E", None, None)), ("C", None, ("F", None, None)))

def pre(n):     return [] if not n else [n[0]] + pre(n[1]) + pre(n[2])
def inorder(n): return [] if not n else inorder(n[1]) + [n[0]] + inorder(n[2])
def post(n):    return [] if not n else post(n[1]) + post(n[2]) + [n[0]]

def level(root):
    out, q = [], deque([root])
    while q:
        n = q.popleft()
        if n:
            out.append(n[0]); q.extend([n[1], n[2]])
    return out

print("pre  ", pre(tree))       # ['A', 'B', 'D', 'E', 'C', 'F']
print("in   ", inorder(tree))   # ['D', 'B', 'E', 'A', 'C', 'F']
print("post ", post(tree))      # ['D', 'E', 'B', 'F', 'C', 'A']
print("level", level(tree))     # ['A', 'B', 'C', 'D', 'E', 'F']
